import apiClient from '@/lib/apiClient';

export interface LoginCredentials {
    email: string;
    password: string;
}

export interface RegisterData {
    email: string;
    password: string;
    passwordConfirm: string;
    fullName: string;
    gender: 'MALE' | 'FEMALE' | 'OTHER';
    dateOfBirth: string; // ISO date string
}

export interface AuthResponse {
    success: boolean;
    data: {
        accessToken: string;
        refreshToken: string | null;
        clientId: string | null;
        isPreAccess: boolean;
        preAccessType: string | null;
    };
    message: string;
}

export interface User {
    _id: string;
    email: string;
    fullName: string;
    avatar?: string;
    gender: string;
    dateOfBirth: string;
    roles: string[];
}

// Login
export const login = async (credentials: LoginCredentials): Promise<AuthResponse> => {
    const { data } = await apiClient.post('/auth/login', credentials);

    // Handle successful login (not pre-access)
    if (data.data && !data.data.isPreAccess) {
        // Save tokens to localStorage
        if (typeof window !== 'undefined') {
            localStorage.setItem('accessToken', data.data.accessToken);
            if (data.data.refreshToken) {
                localStorage.setItem('refreshToken', data.data.refreshToken);
            }
            if (data.data.clientId) {
                localStorage.setItem('clientId', data.data.clientId);
            }
        }
    } else if (data.data && data.data.isPreAccess) {
        // Pre-access token (for verify email or 2FA)
        if (typeof window !== 'undefined') {
            localStorage.setItem('preAccessToken', data.data.accessToken);
            localStorage.setItem('preAccessType', data.data.preAccessType || '');
        }
    }

    return data;
};

// Register
export const register = async (userData: RegisterData): Promise<AuthResponse> => {
    const { data } = await apiClient.post('/auth/register', userData);

    // Save pre-access token for email verification
    if (data.data && data.data.accessToken) {
        if (typeof window !== 'undefined') {
            localStorage.setItem('preAccessToken', data.data.accessToken);
            localStorage.setItem('preAccessType', data.data.preAccessType || '');
        }
    }

    return data;
};

// Verify email with OTP
export const verifyEmail = async (otp: string): Promise<{ success: boolean; message: string }> => {
    const preAccessToken = typeof window !== 'undefined' ? localStorage.getItem('preAccessToken') : null;

    const { data } = await apiClient.post('/auth/verify-email', { otp }, {
        headers: {
            Authorization: `Bearer ${preAccessToken}`,
        },
    });

    // Clear pre-access token after verification
    if (typeof window !== 'undefined') {
        localStorage.removeItem('preAccessToken');
        localStorage.removeItem('preAccessType');
    }

    return data;
};

// Resend verify email
export const resendVerifyEmail = async (): Promise<AuthResponse> => {
    const preAccessToken = typeof window !== 'undefined' ? localStorage.getItem('preAccessToken') : null;

    const { data } = await apiClient.post('/auth/resend-ve', {}, {
        headers: {
            Authorization: `Bearer ${preAccessToken}`,
        },
    });

    return data;
};

// Verify 2FA
export const verify2FA = async (otp: string): Promise<AuthResponse> => {
    const preAccessToken = typeof window !== 'undefined' ? localStorage.getItem('preAccessToken') : null;

    const { data } = await apiClient.post('/auth/verify-2fa', { otp }, {
        headers: {
            Authorization: `Bearer ${preAccessToken}`,
        },
    });

    // Save tokens after successful 2FA
    if (data.data && !data.data.isPreAcesss) {
        if (typeof window !== 'undefined') {
            localStorage.setItem('accessToken', data.data.accessToken);
            if (data.data.refreshToken) {
                localStorage.setItem('refreshToken', data.data.refreshToken);
            }
            if (data.data.clientId) {
                localStorage.setItem('clientId', data.data.clientId);
            }
            localStorage.removeItem('preAccessToken');
            localStorage.removeItem('preAccessType');
        }
    }

    return data;
};

// Logout
export const logout = async (): Promise<void> => {
    try {
        const fcmToken = typeof window !== 'undefined' ? localStorage.getItem('fcmToken') : null;
        await apiClient.post('/auth/logout', { fcmToken });
    } finally {
        // Clear tokens from localStorage
        if (typeof window !== 'undefined') {
            localStorage.removeItem('accessToken');
            localStorage.removeItem('refreshToken');
            localStorage.removeItem('clientId');
            localStorage.removeItem('preAccessToken');
            localStorage.removeItem('preAccessType');
        }
    }
};

// Get current user
export const getCurrentUser = async (): Promise<User> => {
    const { data } = await apiClient.get('/auth/me');
    return data.data;
};

// Google OAuth
export const loginWithGoogle = async (token: string): Promise<AuthResponse> => {
    const { data } = await apiClient.post('/auth/google', { token });

    // Save tokens to localStorage
    if (data.data && !data.data.isPreAcesss) {
        if (typeof window !== 'undefined') {
            localStorage.setItem('accessToken', data.data.accessToken);
            if (data.data.refreshToken) {
                localStorage.setItem('refreshToken', data.data.refreshToken);
            }
            if (data.data.clientId) {
                localStorage.setItem('clientId', data.data.clientId);
            }
        }
    }

    return data;
};

// Forgot password
export const forgotPassword = async (email: string): Promise<AuthResponse> => {
    const { data } = await apiClient.post('/auth/forgot-password', { email });

    if (data.data && data.data.accessToken) {
        if (typeof window !== 'undefined') {
            localStorage.setItem('preAccessToken', data.data.accessToken);
            localStorage.setItem('preAccessType', data.data.preAccessType || '');
        }
    }

    return data;
};

// Reset password
export const resetPassword = async (otp: string, newPassword: string): Promise<{ success: boolean; message: string }> => {
    const preAccessToken = typeof window !== 'undefined' ? localStorage.getItem('preAccessToken') : null;

    const { data } = await apiClient.post('/auth/reset-password', { otp, newPassword }, {
        headers: {
            Authorization: `Bearer ${preAccessToken}`,
        },
    });

    if (typeof window !== 'undefined') {
        localStorage.removeItem('preAccessToken');
        localStorage.removeItem('preAccessType');
    }

    return data;
};
